'use client'
/** Segmented: the MATRIX card `ui-segmented` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-segmented')!

export type MatrixSegmentedProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixSegmented(props: MatrixSegmentedProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
